CREATE TABLE public.agent_memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, content text NOT NULL, category text NOT NULL DEFAULT 'fact', importance int NOT NULL DEFAULT 5, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.agent_memories TO authenticated; GRANT ALL ON public.agent_memories TO service_role; ALTER TABLE public.agent_memories ENABLE ROW LEVEL SECURITY; CREATE POLICY "own memories" ON public.agent_memories FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE TRIGGER t_memories_upd BEFORE UPDATE ON public.agent_memories FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TABLE public.roadmap_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, roadmap_item_id uuid REFERENCES public.roadmap_items(id) ON DELETE CASCADE, roadmap_id uuid REFERENCES public.roadmaps(id) ON DELETE CASCADE, title text NOT NULL, url text NOT NULL, kind text NOT NULL DEFAULT 'article', thumbnail text, duration_text text, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.roadmap_resources TO authenticated; GRANT ALL ON public.roadmap_resources TO service_role; ALTER TABLE public.roadmap_resources ENABLE ROW LEVEL SECURITY; CREATE POLICY "own resources" ON public.roadmap_resources FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);